/* Project 360 authority. Existing jobs remain the identity; stock, purchasing and accounting stay in their source systems. */
let psProjectSelected='',psProjectTab='Overview',psProjectHomeView='Precision Desk',psProjectSearch='',psProjectFilter='all';
const psProjectStages=['Planning','Approved','Procurement','Ready for Site','In Progress','Commercial Review','Ready to Invoice','Completed'];
function psProjectEsc(v){return escapeHtml(String(v??''));}
function psProjectCash(pence){return money(Number(pence||0)/100);}
const psProjectBoardStages=[...psProjectStages,'On Hold','Cancelled'];
function psProjectStage(status){if(['On Hold','Cancelled'].includes(status))return status;if(status==='Invoiced')return 'Completed';if(status==='Enquiry')return 'Planning';if(status==='Pending Parts')return 'Procurement';if(status==='Ready To Invoice')return 'Ready to Invoice';return psProjectStages.includes(status)?status:'Planning';}
function psProjectTable(headers,rows,empty){return '<div class="ps-table-region"><table class="'+(headers.length<=3?'project-table-compact':'project-table-data')+'"><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+(rows||'<tr><td colspan="'+headers.length+'" class="project-360-empty">'+psProjectEsc(empty||'No records yet.')+'</td></tr>')+'</tbody></table></div>';}
function psProjectInput(label,name,value,type='text',extra=''){return '<label>'+label+'<input name="'+name+'" type="'+type+'" value="'+psProjectEsc(value)+'" '+extra+'></label>';}
function psProjectOptions(rows,label){return '<option value="">'+label+'</option>'+rows.map(r=>'<option value="'+psProjectEsc(r.id)+'">'+psProjectEsc(r.name||r.title||r.id)+'</option>').join('');}
function psProjectForm(job,action,body,label,attrs=''){return '<form data-project-form="'+action+'" '+attrs+'><input type="hidden" name="jobId" value="'+psProjectEsc(job.id)+'"><div class="project-360-form-grid">'+body+'</div><button type="submit">'+label+'</button></form>';}
function psProjectQueuedInvoice(job){const p=psProjectModel(job);return (p.phases||[]).filter(ph=>ph.invoiceRequested).reduce((n,ph)=>n+psProjectPence(ph.amountNet||0),0);}
function psProjectProgressRail(job){const current=psProjectStage(job.status),idx=psProjectStages.indexOf(current);return '<div class="project-360-stage-rail" aria-label="Project progress">'+psProjectStages.map((stage,i)=>'<div class="project-360-stage '+(i<idx?'done':i===idx?'current':'')+'"><span>'+(i<idx?'✓':i+1)+'</span><b>'+stage+'</b></div>').join('')+'</div>';}
function psProjectCommercialBar(job,summary){
 const queued=psProjectQueuedInvoice(job),remaining=Math.max(0,summary.revenue-queued),margin=summary.margin===null?'Not set':summary.margin.toFixed(1)+'%';
 return '<section class="project-360-commercial-bar" aria-label="Project commercial position">'+[
 ['Quoted / contract',psProjectCash(summary.quote)],['Forecast final cost',psProjectCash(summary.forecast)],['Projected profit',summary.margin===null?'Set contract':psProjectCash(summary.profit)],['Projected margin',margin],['Approved variations',psProjectCash(summary.approvedExtra)],['Invoiced / queued',psProjectCash(queued)],['Remaining to invoice',psProjectCash(remaining)]
 ].map(([label,value],i)=>'<div class="'+(i<4?'project-metric-primary':'project-metric-secondary')+'"><span>'+label+'</span><strong>'+value+'</strong></div>').join('')+'</section>';
}
function psProjectFiltered(rows){const search=psProjectSearch.trim().toLowerCase();return rows.filter(x=>{
 const closed=['Completed','Invoiced','Cancelled'].includes(x.job.status),risk=['At Risk','Critical'].includes(x.health.level);
 const matches=psProjectFilter==='all'||psProjectFilter==='active'&&!closed||psProjectFilter==='risk'&&risk||psProjectFilter==='invoice'&&x.summary.invoiceExposure?.thresholdTriggered||psProjectFilter==='closed'&&closed;
 return matches&&(!search||[x.job.id,x.job.name,customer(x.job.customerId)?.name,x.job.owner].join(' ').toLowerCase().includes(search));
});}
function psProjectFinder(shown,total){return '<form class="project-finder" data-project-search-form><label>Find a project<input name="search" type="search" placeholder="Project, customer, reference or owner" value="'+psProjectEsc(psProjectSearch)+'"></label><label>Show<select name="filter">'+[['all','All projects'],['active','Active projects'],['risk','Margin at risk'],['invoice','Invoice review'],['closed','Completed / cancelled']].map(([value,label])=>'<option value="'+value+'" '+(value===psProjectFilter?'selected':'')+'>'+label+'</option>').join('')+'</select></label><button type="submit">Search</button><button type="button" class="secondary" data-project-clear-search>Clear</button><span role="status">'+shown+' of '+total+' projects</span></form>';}
function psProjectNavigation(tabs){const groups=[['Project',['Overview','Scope & Tasks','Site Notes & Files']],['Delivery',['Orders & Pricing','Materials','Procurement','Stock & Job Bin','Tools']],['Commercial',['Costing & Margin','Extras & Approvals','Billing & Variations']],['Record',['Correspondence','Activity','Settings']]];return '<nav class="project-360-tabs" aria-label="Project Details sections">'+groups.map(([label,items])=>'<div class="project-nav-group"><span>'+label+'</span><div>'+items.filter(t=>tabs.includes(t)).map(t=>'<button type="button" class="'+(psProjectTab===t?'active':'')+'" data-project-tab="'+t+'" '+(psProjectTab===t?'aria-current="page"':'')+'>'+t+'</button>').join('')+'</div></div>').join('')+'</nav>';}

function psProjectNextAction(job,summary,health){if(health.level==='Critical')return 'Commercial review required before further commitment.';if(summary.invoiceExposure?.thresholdTriggered)return 'Review progress invoice exposure.';if(summary.stock?.lines.some(x=>x.inbound>0))return 'Monitor inbound project materials and supplier ETAs.';if((psProjectModel(job).tasks||[]).some(t=>t.status!=='Done'))return 'Complete the next outstanding project task.';if(summary.margin!==null&&summary.margin<summary.target)return 'Review margin recovery opportunities.';return 'Project is commercially on track. Review the next milestone.';}
function psProjectHome(){
 const jobs=(data.jobs||[]).slice(),summaries=jobs.map(job=>({job,summary:psProjectSummary(job)})).map(x=>({...x,health:psProjectHealth(x.job,x.summary)}));
 const atRisk=summaries.filter(x=>['At Risk','Critical'].includes(x.health.level)).length,invoice=summaries.filter(x=>x.summary.invoiceExposure?.thresholdTriggered).length,material=summaries.filter(x=>x.summary.stock?.lines.some(l=>l.inbound>0)).length;
 const filtered=psProjectFiltered(summaries),finder=psProjectFinder(filtered.length,summaries.length);
 const head='<header class="project-360-home-head"><div><span class="project-360-kicker">PROJECTS / COMMERCIAL CONTROL</span><h1>Projects</h1><p>Manage stock, supplier commitments, project cost, margin and invoice exposure from one live record.</p></div><div class="project-360-actions"><button class="secondary" aria-pressed="'+(psProjectHomeView==='Stage Board')+'" data-project-home-view="Stage Board">Stage Board</button><button class="secondary" aria-pressed="'+(psProjectHomeView==='Precision Desk')+'" data-project-home-view="Precision Desk">Precision Desk</button><button data-project-new>+ New project</button></div></header>';
 const metrics='<section class="project-360-home-metrics"><div><span>Open projects</span><strong>'+summaries.filter(x=>!['Completed','Invoiced','Cancelled'].includes(x.job.status)).length+'</strong><small>active records</small></div><div><span>Margin risk</span><strong>'+atRisk+'</strong><small>at risk / critical</small></div><div><span>Invoice review</span><strong>'+invoice+'</strong><small>exposure threshold</small></div><div><span>Inbound materials</span><strong>'+material+'</strong><small>projects waiting</small></div></section>';
 if(psProjectHomeView==='Stage Board'){
  const board='<div class="project-stage-board">'+psProjectBoardStages.map(stage=>{const rows=filtered.filter(x=>psProjectStage(x.job.status)===stage);return '<section class="project-stage-lane"><header><span>'+stage+'</span><b>'+rows.length+'</b></header>'+rows.map(x=>'<button data-project-open="'+psProjectEsc(x.job.id)+'" class="project-stage-card"><strong>'+psProjectEsc(x.job.name)+'</strong><small>'+psProjectEsc(customer(x.job.customerId)?.name||'No customer')+'</small><span class="project-health '+x.health.tone+'">'+x.health.level+'</span><em>'+(x.summary.margin===null?'Margin not set':x.summary.margin.toFixed(1)+'% margin')+'</em></button>').join('')+'</section>';}).join('')+'</div>';
  return '<section class="project-360-home">'+head+metrics+finder+'<div class="project-360-view-label"><b>Stage Board</b><span>Planning view by project lifecycle.</span></div>'+board+'</section>';
 }
 const rows=filtered.slice().sort((a,b)=>{const rank={Critical:0,'At Risk':1,Attention:2,Healthy:3};return rank[a.health.level]-rank[b.health.level]||String(a.job.id).localeCompare(String(b.job.id));}).map(x=>{const s=x.summary,bin=s.stock?.jobBin;return '<tr><td><button class="link-button" data-project-open="'+psProjectEsc(x.job.id)+'"><strong>'+psProjectEsc(x.job.name)+'</strong></button><small>'+psProjectEsc(x.job.id)+' · '+psProjectEsc(customer(x.job.customerId)?.name||'No customer')+'</small></td><td><span class="project-health '+x.health.tone+'">'+x.health.level+'</span><small>'+psProjectEsc(psProjectNextAction(x.job,s,x.health))+'</small></td><td>'+psProjectEsc(psProjectStage(x.job.status))+'</td><td><strong>'+(s.margin===null?'—':s.margin.toFixed(1)+'%')+'</strong><small>target '+s.target+'% · min '+s.minimumMargin+'%</small></td><td>'+psProjectCash(s.forecast)+'<small>'+psProjectCash(s.profit)+' projected profit</small></td><td>'+((s.stock?.lines||[]).filter(l=>l.inbound>0).length)+' lines<small>'+psProjectEsc(bin?.name||'No Job Bin')+'</small></td><td>'+psProjectCash(s.invoiceExposure?.exposureGap||0)+'<small>'+(s.invoiceExposure?.thresholdTriggered?'review recommended':'within threshold')+'</small></td><td><button data-project-open="'+psProjectEsc(x.job.id)+'">Open</button></td></tr>';}).join('');
 return '<section class="project-360-home">'+head+metrics+finder+'<div class="project-360-view-label"><b>Precision Desk</b><span>Exception-first project control. Oldest problems and commercial risk surface first.</span></div>'+psProjectTable(['Project','Health / next action','Stage','Projected margin','Forecast / profit','Materials','Invoice exposure',''],rows,summaries.length?'No projects match your search. Clear the filters to see all projects.':'No projects yet. Use New project to get started.')+'</section>';
}
function psProjectOverview(job,p,s,health){
 const floor=s.minimumMargin,headroom=Math.round(s.revenue*(1-floor/100))-s.forecast,warning=Number(p.warningMargin??25),tone=s.missingCosts?'warn':s.margin===null?'warn':s.margin<floor?'bad':s.margin<warning?'warn':'good';
 const pending=p.variations.filter(v=>v.status==='Proposed'),pendingCost=pending.reduce((n,v)=>n+psProjectPence(v.costNet||0),0),openFollowups=p.correspondence.filter(c=>c.followUp&&!c.completedAt);
 return '<section class="project-margin-band '+tone+'"><div><span>Forecast project margin</span><strong>'+(s.missingCosts?'Unverified':s.margin===null?'Not set':s.margin.toFixed(1)+'%')+'</strong></div><div><h3>'+(s.missingCosts?'Missing costs need review':headroom<0?'Below the '+floor+'% minimum':'Above the '+floor+'% minimum')+'</h3><p>'+psProjectCash(Math.abs(headroom))+(headroom<0?' over the minimum-margin cost ceiling.':' cost headroom before the minimum.')+' Target '+s.target+'%.</p><small>Unspent risk buffer '+money(p.riskBufferNet||0)+' · Headroom after buffer '+psProjectCash(headroom-psProjectPence(p.riskBufferNet||0))+'</small></div></section><div class="project-360-two-col"><section class="project-360-card"><header><div><h3>What needs attention</h3><p>Live checks from this project’s records.</p><p>Open Sales Orders: '+s.orders.filter(o=>!['Shipped','Invoiced','Completed','Cancelled'].includes(o.status)).length+' · Open Purchase Orders: '+s.poRows.filter(r=>r.open>0).length+'</p></div></header><div class="project-144-pad">'+s.alerts.map(a=>'<div class="project-360-alert '+a.severity+'">'+psProjectEsc(a.text)+'</div>').join('')+(s.alerts.length?'':'<p>No current commercial exceptions.</p>')+'</div></section><section class="project-360-card"><header><div><h3>Original scope & extras</h3><p>Proposed prices are not yet agreed revenue.</p></div></header>'+psProjectTable(['Scope','Selling value'],[['Original accepted quote',s.quote],['Customer-approved extras',s.approvedExtra],['Pending extras',s.pendingExtra]].map(([name,n])=>'<tr><td>'+name+'</td><td>'+psProjectCash(n)+'</td></tr>').join(''))+'<div class="project-144-pad"><p>'+pending.length+' extras await a decision. Potential extra cost: '+psProjectCash(pendingCost)+'.</p><p>'+openFollowups.length+' open correspondence follow-ups.</p></div></section><section class="project-360-card"><header><div><h3>Cost position</h3><p>Each source contributes once to the forecast.</p></div></header>'+psProjectTable(['Cost position','Net'],[['Actual costs',s.actual],['Received estimates',s.estimatedReceived],['Outstanding commitments',s.committed],['Remaining estimate',s.uncommitted],['Tools and hire',s.tools]].map(([name,n])=>'<tr><td>'+name+'</td><td>'+psProjectCash(n)+'</td></tr>').join(''))+'</section><section class="project-360-card"><header><div><h3>Invoice recommendations</h3><p>Only agreed, completed stages qualify for review.</p></div></header><div class="project-144-pad">'+s.recommendations.map(r=>'<p>'+psProjectEsc(r.text)+'</p>').join('')+(!s.recommendations.length?'<p>No unqueued invoice stages. Review the agreed schedule in Billing.</p>':'')+'</div></section></div>';
}
function psProjectScopeTasks(job,p){
 const phaseOpts=psProjectOptions((p.phases||[]).filter(ph=>!ph.ready),'No invoice stage');
 return '<div class="project-360-two-col"><section class="project-360-card"><header><div><h3>Scope & Tasks</h3><p>Owner, due date and billing-stage context for every outstanding action.</p></div></header>'+psProjectForm(job,'task',psProjectInput('Task','title','','text','required')+psProjectInput('Owner','owner','','text','required')+psProjectInput('Due date','due','','date')+'<label>Billing stage<select name="phaseId">'+phaseOpts+'</select></label>','Add task')+psProjectTable(['Task','Owner','Due','Stage','Status',''],(p.tasks||[]).map(t=>'<tr><td>'+psProjectEsc(t.title)+'</td><td>'+psProjectEsc(t.owner)+'</td><td>'+psProjectEsc(t.due||'—')+'</td><td>'+psProjectEsc((p.phases||[]).find(ph=>ph.id===t.phaseId)?.name||'General')+'</td><td>'+psProjectEsc(t.status)+'</td><td>'+(t.status!=='Done'?'<button data-project-task-done="'+psProjectEsc(t.id)+'">Complete</button>':'')+'</td></tr>').join(''),'No tasks yet.')+'</section><aside class="project-360-card"><header><div><h3>Project scope record</h3><p>Commercially relevant site scope stays on the master Project.</p></div></header><p><strong>Status:</strong> '+psProjectEsc(job.status)+'</p><p><strong>Owner:</strong> '+psProjectEsc(job.owner||'Not assigned')+'</p><p><strong>Customer reference:</strong> '+psProjectEsc(job.customerRef||'Not set')+'</p><p><strong>Notes:</strong><br>'+psProjectEsc(job.notes||'No project notes recorded.')+'</p><button class="secondary" data-project-edit-record>Edit project record</button></aside></div>';
}
function psProjectMaterials(job,p,s){
 const productOptions=psProjectOptions((data.products||[]).filter(x=>!x.deleted).map(x=>({id:x.id,name:(x.sku||x.id)+' · '+x.name})),'Choose product');
 const rows=(s.stock?.lines||[]).map(x=>'<tr><td><strong>'+psProjectEsc(x.sku)+'</strong><small>'+psProjectEsc(x.name)+'</small></td><td>'+x.planned+'</td><td>'+x.allocated+'</td><td>'+x.inbound+'</td><td>'+x.jobBin+'</td><td>'+x.used+'</td><td>'+x.returnPending+'</td><td>'+x.damagedLost+'</td><td>'+psProjectCash(x.budgetCost)+'</td><td>'+psProjectCash(x.forecastMaterialCost)+'</td><td class="'+(x.costVariance>0?'bad-text':'good-text')+'">'+psProjectCash(x.costVariance)+'</td><td>'+(p.materialPlan.find(m=>m.productId===x.productId)?'<button class="secondary" data-project-material-remove="'+psProjectEsc(p.materialPlan.find(m=>m.productId===x.productId).id)+'">Remove plan</button>':'')+'</td></tr>').join('');
 return '<section class="project-360-card" data-project-material-plan><header><div><h3>Material plan & live readiness</h3><p>Planned quantities are compared with real allocations, inbound POs and Job Bin stock. The plan is a budget, not a second stock ledger.</p></div><div class="project-360-card-total"><span>Material variance</span><strong class="'+(s.materialVariance>0?'bad-text':'good-text')+'">'+psProjectCash(s.materialVariance)+'</strong></div></header>'+psProjectForm(job,'material-plan','<label>Product<select name="productId" required>'+productOptions+'</select></label>'+psProjectInput('Planned quantity','plannedQty',1,'number','min="0.01" step="0.01" required')+psProjectInput('Budget unit cost (£)','budgetUnitCost',0,'number','min="0" step="0.01" required')+psProjectInput('Planning note','note',''),'Save material plan')+psProjectTable(['Item','Planned','Allocated','Inbound','Job Bin','Used','Return pending','Damaged / lost','Budget','Forecast','Variance',''],rows,'No project material plan or live project stock yet.')+'</section>';
}
function psProjectProcurement(job,s){
 const rows=s.poRows.map(r=>{const pending=r.po.lines.reduce((n,l)=>n+Math.max(0,Number(l.qty||0)-Number(l.received||0)),0);return '<tr><td><button class="link-button" data-open-po="'+psProjectEsc(r.po.id)+'"><strong>'+psProjectEsc(r.po.id)+'</strong></button><small>'+psProjectEsc(r.po.supplier||'Supplier')+'</small></td><td>'+psProjectEsc(r.po.status||'Draft')+'</td><td>'+psProjectEsc(r.po.due||'Not set')+'</td><td>'+psProjectCash(r.total)+'</td><td>'+psProjectCash(r.received)+'</td><td>'+psProjectCash(r.open)+'</td><td>'+pending+'</td><td><button data-open-po="'+psProjectEsc(r.po.id)+'">Open PO</button></td></tr>';}).join('');
 return '<section class="project-360-card"><header><div><h3>Procurement</h3><p>Every supplier commitment linked to this Project. Purchase Orders remain the supplier-side order authority.</p></div></header>'+psProjectTable(['PO / supplier','Status','ETA','Ordered cost','Received estimate','Still committed','Units outstanding',''],rows,'No Purchase Orders are linked to this Project.')+'<div class="project-360-rule"><b>Project demand does not own physical stock.</b><span>Warehouse booking-in and FIFO allocation remain authoritative after QC.</span></div></section>';
}
function psProjectStock(job,s){
 const bin=s.stock?.jobBin,productOptions=(s.stock?.lines||[]).filter(x=>x.jobBin>0).map(x=>({id:x.productId,name:x.sku+' · '+x.name+' · '+x.jobBin+' on hand'}));
 const actions=bin?'<div class="project-360-two-col"><form data-project-form="stock-use" data-project-stock-use><input type="hidden" name="jobId" value="'+psProjectEsc(job.id)+'"><h4>Record Project Use</h4><label>Product<select name="productId" required>'+psProjectOptions(productOptions,'Choose Job Bin stock')+'</select></label>'+psProjectInput('Quantity','qty',1,'number','min="0.01" step="0.01" required')+psProjectInput('Reason / location used','reason','','text','required')+'<button type="submit">Record use</button></form><form data-project-form="stock-damage" data-project-stock-damage><input type="hidden" name="jobId" value="'+psProjectEsc(job.id)+'"><h4>Record damaged / lost</h4><label>Product<select name="productId" required>'+psProjectOptions(productOptions,'Choose Job Bin stock')+'</select></label>'+psProjectInput('Quantity','qty',1,'number','min="0.01" step="0.01" required')+psProjectInput('Reason','reason','','text','required')+'<button type="submit" class="danger-button">Record damage / loss</button></form></div>':'<div class="project-360-empty-action"><p>No Project Job Bin is linked yet.</p><button data-project-create-bin>Create Project Job Bin</button></div>';
 const rows=(s.stock?.lines||[]).map(x=>'<tr><td><strong>'+psProjectEsc(x.sku)+'</strong><small>'+psProjectEsc(x.name)+'</small></td><td>'+x.jobBin+'</td><td>'+x.used+'</td><td>'+x.returnPending+'</td><td>'+x.damagedLost+'</td><td>'+psProjectCash(x.forecastMaterialCost)+'</td></tr>').join('');
 return '<section class="project-360-card"><header><div><h3>Stock & Job Bin</h3><p>Physical Project stock is read from '+psProjectEsc(bin?.name||'the Project Job Bin')+'. Actions use the shared stock movement engine.</p></div><button class="secondary" data-project-open-warehouse>Open Warehouse</button></header><div class="project-360-rule"><b>Warehouse remains stock truth.</b><span>Project Use or damage reduces only free stock and creates an auditable movement. Allocated stock cannot be consumed accidentally.</span></div>'+actions+psProjectTable(['Item','Job Bin','Used','Return pending','Damaged / lost','Material forecast'],rows,'No stock is currently associated with this Project.')+'</section>';
}
function psProjectCosting(job,p,s){
 const hasRevenue=s.revenue>0;
 const metric=(label,value,help,cls='')=>'<div class="'+cls+'"><span>'+label+'</span><strong>'+value+'</strong><small>'+help+'</small></div>';
 const metrics='<section class="project-profit-metrics" aria-label="Project profit forecast">'+metric('Agreed selling value',psProjectCash(s.revenue),'Contract plus approved extras, ex VAT')+metric('Forecast final cost',psProjectCash(s.forecast),'Recorded, committed and still to spend')+metric('Forecast profit',hasRevenue?psProjectCash(s.profit):'Set contract value',hasRevenue?'Selling value less forecast final cost':'Open project commercial settings',hasRevenue&&s.profit<0?'is-loss':'')+metric('Forecast margin',hasRevenue?s.margin.toFixed(1)+'%':'Not calculated','Target '+s.target+'% · Minimum '+s.minimumMargin+'%',hasRevenue&&s.margin<s.minimumMargin?'is-loss':'')+metric(s.headroom<0?'Over target cost budget':'Cost headroom to target',hasRevenue?psProjectCash(Math.abs(s.headroom)):'Not calculated',s.headroom<0?'Cost reduction needed to reach target':'Extra cost affordable before missing target',hasRevenue&&s.headroom<0?'is-loss':'')+'</section>';
 const alerts='<div class="project-profit-alerts">'+s.alerts.map(a=>'<div class="project-360-alert '+a.severity+'"><span>'+psProjectEsc(a.text)+'</span></div>').join('')+'</div>';
 const totals='<section class="project-360-card"><header><div><h3>Where the money goes</h3><p>All amounts exclude VAT. Each cost appears once in the forecast.</p></div></header><div class="project-360-mini-grid">'+[['Actual recorded costs',s.actual],['Received PO estimates',s.estimatedReceived],['Outstanding commitments',s.committed],['Remaining forecast',s.uncommitted],['Tools / hire',s.tools],['Forecast final cost',s.forecast]].map(([label,value])=>'<div><span>'+label+'</span><strong>'+psProjectCash(value)+'</strong></div>').join('')+'</div>'+psProjectTable(['Margin driver','Impact'],s.marginMovement.map(m=>'<tr><td>'+psProjectEsc(m.label)+'</td><td>'+psProjectCash(m.amount)+'</td></tr>').join(''))+'</section>';
 const forecast='<section class="project-360-card"><header><div><h3>Cost still to come</h3><p>Allow for unfinished labour and other costs that are not already in orders, POs, commitments, tools or approved extras. Reduce this allowance as those costs are recorded.</p></div></header>'+psProjectForm(job,'forecast',psProjectInput('Additional remaining cost (£)','remainingNet',p.remainingNet||0,'number','min="0" step="0.01" required'),'Update remaining forecast')+'<div class="project-360-rule"><b>Keep the forecast current</b><span>Recorded costs alone do not show the final profit if work is still outstanding.</span></div></section>';
 const orders=psProjectTable(['Linked sales order','Status','Estimate outside POs','Replaced by actual costs','Still in forecast'],s.orderCostCoverage.map(o=>'<tr><td>'+psProjectEsc(o.id)+'</td><td>'+psProjectEsc(o.status)+'</td><td>'+psProjectCash(o.estimate)+'</td><td>'+psProjectCash(o.matched)+'</td><td>'+psProjectCash(o.remaining)+'</td></tr>').join(''),'No active sales orders linked. Allocate an order in Orders & Pricing.');
 const orderCard='<section class="project-360-card"><header><div><h3>Linked sales order costs</h3><p>Costs follow orders assigned to this project. PO-covered quantities are counted in procurement instead. Order selling values are not added again to the project contract.</p></div></header>'+orders+'</section>';
 const scopeSelect='<label>Allocate cost to<select name="variationId">'+psProjectOptions(p.variations.filter(v=>v.status==='Approved'),'Original project scope')+'</select></label><label>General remaining allowance<select name="replaceRemaining"><option value="no">Keep remaining allowance</option><option value="yes">Replace allowance with this actual cost</option></select></label>';
 const matchOrder='<label>Replace a sales order estimate<select name="orderId">'+psProjectOptions(s.orderCostCoverage.filter(o=>o.remaining>0).map(o=>({id:o.id,name:o.id+' · '+psProjectCash(o.remaining)+' remaining'})),'No order / additional cost')+'</select></label>';
 const labour='<section class="project-360-card"><header><div><h3>Record labour</h3><p>Use your hourly employment cost, including employer costs where applicable, rather than the customer charge-out rate.</p></div></header>'+psProjectForm(job,'time',psProjectInput('Employee / team member','supplier','','text','required')+psProjectInput('Timesheet reference','ref','','text','required')+psProjectInput('Work date','date',todayIso(),'date','required')+psProjectInput('Hours worked','hours','','number','min="0.01" step="0.01" required')+psProjectInput('Cost per hour (£)','hourlyRate','','number','min="0.01" step="0.01" required')+psProjectInput('Work carried out','notes','')+scopeSelect+matchOrder+psProjectInput('Order estimate replaced (£)','coverageNet',0,'number','min="0" step="0.01"'),'Record labour cost')+'<div class="project-360-rule"><b>Hours × hourly cost</b><span>Saved as an actual Labour expense. Match an estimate only if the same labour is already costed in a linked order.</span></div></section>';
 const expenses='<section class="project-360-card"><header><div><h3>Add project cost</h3><p>Record subcontractors, travel, materials and other expenses. Match an actual bill to either a PO or sales order estimate to avoid counting it twice. Correct an existing manual commitment before recording its actual replacement.</p></div></header>'+psProjectForm(job,'cost',psProjectInput('Supplier / employee','supplier','','text','required')+psProjectInput('Reference','ref','','text','required')+psProjectInput('Net cost (£)','net','','number','min="0" step="0.01" required')+psProjectInput('Date','date',todayIso(),'date','required')+'<label>Category<select name="category">'+['Materials','Labour','Subcontractor','Travel','Equipment','Overheads','Other'].map(x=>'<option>'+x+'</option>').join('')+'</select></label><label>Cost status<select name="state"><option>Actual</option><option>Committed</option></select></label><label>Match actual bill to PO<select name="poId">'+psProjectOptions(s.poRows.map(r=>({id:r.po.id,name:r.po.id})),'No PO / separate expense')+'</select></label>'+scopeSelect+matchOrder+psProjectInput('Estimate replaced (£)','coverageNet',0,'number','min="0" step="0.01"')+psProjectInput('Notes','notes',''),'Record cost')+'</section>';
 const categoryRows=s.costCategories.map(c=>'<tr><td>'+psProjectEsc(c.name)+'</td><td>'+psProjectCash(c.actual)+'</td><td>'+psProjectCash(c.committed)+'</td><td>'+psProjectCash(c.actual+c.committed)+'</td></tr>').join('');
 const categories='<section class="project-360-card"><header><div><h3>Recorded costs by category</h3><p>Breakdown of the cost ledger only. PO estimates, remaining allowances and tool allocations are shown in the forecast above.</p></div></header>'+psProjectTable(['Category','Actual','Committed','Recorded total'],categoryRows,'No project costs recorded.')+'</section>';
 const costRows=(p.costs||[]).slice().reverse().map(c=>'<tr><td>'+psProjectEsc(c.date||'')+'<small>'+psProjectEsc(c.ref)+'</small></td><td>'+psProjectEsc(c.supplier)+'<small>'+psProjectEsc(c.notes||'')+'</small></td><td>'+psProjectEsc(c.category)+(c.hours?'<small>'+psProjectEsc(c.hours)+' hours × '+money(c.hourlyRate)+'</small>':'')+'</td><td>'+money(c.net)+'</td><td>'+psProjectEsc(c.voidedAt?'Corrected / excluded':c.state)+'</td><td>'+psProjectEsc(c.poId||c.orderId||'Additional cost')+(c.coverageNet?'<small>'+money(c.coverageNet)+' estimate replaced</small>':'')+'</td><td>'+(!c.voidedAt?'<button class="secondary" data-project-void="'+psProjectEsc(c.id)+'">Correct</button>':psProjectEsc(c.voidReason))+'</td></tr>').join('');
 return '<div class="project-profit-control"><header class="project-profit-heading"><div><h2>Costing & Margin</h2><p>Know what this project is expected to earn after all costs.</p></div><button class="secondary" data-project-tab="Settings">Contract & margin targets</button></header>'+metrics+alerts+'<div class="project-profit-grid">'+totals+forecast+'</div>'+orderCard+'<div class="project-profit-grid">'+labour+expenses+'</div>'+categories+'<section class="project-360-card"><header><div><h3>Cost ledger</h3><p>Corrections exclude a cost from totals and retain the original audit record.</p></div></header>'+psProjectTable(['Date / ref','Supplier / notes','Category / hours','Net','Status','Replaces',''],costRows,'No project costs recorded.')+'</section></div>';
}

function psProjectBilling(job,p,s){
 const finance=typeof psFinanceSnapshot==='function'?psFinanceSnapshot():null;
 const variations=(p.variations||[]).map(v=>'<tr><td>'+psProjectEsc(v.title)+'</td><td>'+money(v.sellNet)+'</td><td>'+money(v.costNet)+'</td><td>'+psProjectEsc(v.status)+'</td><td>'+(v.status==='Proposed'?'<button data-project-approve="'+psProjectEsc(v.id)+'">Record approval</button> <button class="secondary" data-project-reject="'+psProjectEsc(v.id)+'">Reject</button>':psProjectEsc(v.approvalRef||''))+'</td></tr>').join('');
 const phases=(p.phases||[]).map(ph=>{const d=finance?.documents?.find(d=>d.source_id==='PROJECT:'+job.id+':'+ph.id);return '<tr><td>'+psProjectEsc(ph.name)+'</td><td>'+money(ph.amountNet)+'</td><td>'+psProjectEsc(ph.due||'—')+'</td><td>'+(ph.ready?'Ready':'Incomplete')+'</td><td data-project-payment="'+psProjectEsc(ph.id)+'">'+psProjectEsc(d?d.status+(d.xero_number?' · '+d.xero_number:''):ph.invoiceRequested?'Queued for accounting':'Not queued')+'</td><td>'+(ph.invoiceRequested?'':ph.ready?'<button data-project-invoice="'+psProjectEsc(ph.id)+'">Review invoice</button>':'<button data-project-ready="'+psProjectEsc(ph.id)+'">Mark complete</button>')+'</td></tr>';}).join('');
 return '<div class="project-360-two-col"><section class="project-360-card"><header><div><h3>Invoice exposure</h3><p>Milestones and commercial exposure work together. Alerts never issue an invoice automatically.</p></div><span class="project-health '+(s.invoiceExposure.thresholdTriggered?'warn':'good')+'">'+(s.invoiceExposure.thresholdTriggered?'Review recommended':'Within threshold')+'</span></header><div class="project-360-exposure"><span>Cost exposure</span><strong>'+psProjectCash(s.invoiceExposure.costExposure)+'</strong><span>Invoiced / queued</span><strong>'+psProjectCash(s.invoiceExposure.invoicedQueued)+'</strong><span>Exposure gap</span><strong>'+psProjectCash(s.invoiceExposure.exposureGap)+'</strong><span>Cost trigger</span><strong>'+p.invoiceExposureThresholdPct+'%</strong></div><button class="secondary" data-project-finance-refresh>Refresh accounting status</button></section><aside id="psProjectInvoiceReview" class="project-360-card"><header><div><h3>Invoice review</h3><p>Select a ready stage to prepare a reviewed Xero draft.</p></div></header><p>No stage selected.</p></aside></div><section class="project-360-card"><header><div><h3>Invoice milestones</h3><p>Planned '+psProjectCash(s.phaseTotal)+' of '+psProjectCash(s.revenue)+' agreed Project revenue.</p></div></header>'+psProjectForm(job,'phase','<label>Billing scope<select name="variationId">'+psProjectOptions(p.variations.filter(v=>v.status==='Approved'),'Original scope')+'</select></label>'+psProjectInput('Stage name','name','','text','required')+psProjectInput('Net stage amount (£)','amountNet','','number','min="0.01" step="0.01" required')+psProjectInput('Planned billing date','due','','date')+psProjectInput('Agreed billing condition / reference','agreement','','text','required')+'<label>After stage<select name="dependencyId">'+psProjectOptions(p.phases,'No preceding stage')+'</select></label>','Add invoice stage')+psProjectTable(['Stage','Net amount','Due','Completion','Accounting','Action'],phases,'No invoice stages configured.')+'</section>';
}
function psProjectDocuments(job,p){return '<section class="project-360-card"><header><div><h3>Site Notes & Files</h3><p>Site notes stay on the Project. Documents can remain local or sync to private shared storage.</p></div></header><div class="project-360-site-note"><span>Current project notes</span><p>'+psProjectEsc(job.notes||'No site/project notes recorded.')+'</p><button class="secondary" data-project-edit-record>Edit notes</button></div><label class="ps-project-upload">Add drawings, approvals, invoices or photos<input id="psProjectFiles" multiple accept="application/pdf,image/png,image/jpeg"></label><button class="secondary" data-project-doc-sync>Sync local documents</button>'+psProjectTable(['File','Reference','Storage','Download'],(p.documents||[]).map(d=>'<tr><td>'+psProjectEsc(d.name)+'</td><td>'+psProjectEsc(d.reference||'')+'</td><td>'+psProjectEsc(d.storagePath?'Shared private storage':'This device only — upload pending')+'</td><td><button data-project-file="'+psProjectEsc(d.id)+'">Download</button></td></tr>').join(''),'No documents yet.')+'</section>';}
function psProjectActivity(job,p){const moves=(data.movements||[]).filter(m=>m.ref===job.id).slice().reverse().map(m=>'<tr><td>'+psProjectEsc(m.date||'')+'</td><td>'+psProjectEsc(m.type)+'</td><td>'+psProjectEsc(product(m.productId)?.sku||m.productId||'—')+'</td><td>'+psProjectEsc(m.qty||'')+'</td><td>'+psProjectEsc(m.user||'')+'</td><td>'+psProjectEsc(m.note||'')+'</td></tr>').join('');const audit=(p.audit||[]).slice().reverse().map(a=>'<tr><td>'+psProjectEsc(a.at)+'</td><td>'+psProjectEsc(a.user)+'</td><td>'+psProjectEsc(a.action)+'</td><td>'+psProjectEsc(JSON.stringify(a.details||{}))+'</td></tr>').join('');return '<section class="project-360-card"><header><div><h3>Activity</h3><p>Commercial changes and physical Project stock movements remain auditable.</p></div></header><h4>Project audit</h4>'+psProjectTable(['When','User','Action','Details'],audit,'No Project audit history.')+'<h4>Project stock movements</h4>'+psProjectTable(['Date','Movement','Item','Qty','User','Reason'],moves,'No Project stock movements.')+'</section>';}
function psProjectSettings(job,p){return '<section class="project-360-card"><header><div><h3>Project commercial settings</h3><p>Project-specific controls. Customer-approved prices and invoice terms remain protected.</p></div></header>'+psProjectForm(job,'settings',psProjectInput('Accepted quote total excluding VAT (£)','quoteNet',p.quoteNet,'number','min="0" step="0.01" required '+(p.quoteAccepted?'readonly':''))+psProjectInput('Quote / acceptance reference','quoteRef',p.quoteRef)+psProjectInput('Minimum margin (%)','minimumMargin',p.minimumMargin,'number','min="0" max="99" step="0.1" required')+psProjectInput('Warn below margin (%)','warningMargin',p.warningMargin,'number','min="0" max="99" step="0.1" required')+psProjectInput('Target margin (%)','targetMargin',p.targetMargin,'number','min="0" max="99" step="0.1" required')+psProjectInput('Critical near-loss threshold (%)','lossWarningMargin',p.lossWarningMargin,'number','min="0" max="99" step="0.1" required')+psProjectInput('Unspent risk buffer (£)','riskBufferNet',p.riskBufferNet||0,'number','min="0" step="0.01" required')+psProjectInput('Project owner','owner',job.owner||'','text','required')+psProjectInput('Next cost review','reviewDue',p.reviewDue||'','date')+psProjectInput('Target completion','targetCompletion',p.targetCompletion||'','date')+'<label>Project success goals<textarea name="goal" maxlength="1500">'+psProjectEsc(p.goal||'')+'</textarea></label>'+psProjectInput('Additional remaining cost not already counted (£)','remainingNet',p.remainingNet,'number','min="0" step="0.01" required')+psProjectInput('Invoice cost exposure threshold (%)','invoiceExposureThresholdPct',p.invoiceExposureThresholdPct,'number','min="0" max="100" step="1" required')+psProjectInput('Optional uncovered exposure trigger (£)','invoiceExposureThresholdNet',p.invoiceExposureThresholdNet,'number','min="0" step="0.01" required')+psProjectInput('Reason for settings change','settingsReason','','text','required')+'<label class="ps-project-check"><input type="checkbox" name="quoteAccepted" '+(p.quoteAccepted?'checked disabled':'')+'> Customer accepted this quote</label>','Save project settings')+'<div class="project-360-rule"><b>Minimum ≤ warning ≤ target</b><span>Lowering the minimum weakens protection. The risk buffer reserves headroom without adding another forecast expense. All changes are retained in project history.</span></div></section>';}

function psProjectWorkspace(){
 const job=(data.jobs||[]).find(x=>x.id===psProjectSelected);if(!job)return psProjectHome();
 const p=psProjectModel(job),s=psProjectSummary(job),liveStock=psProjectStockSummary(job);s.stock=liveStock;const health=psProjectHealth(job,s),tabs=['Overview','Orders & Pricing','Extras & Approvals','Correspondence','Scope & Tasks','Materials','Procurement','Stock & Job Bin','Tools','Costing & Margin','Billing & Variations','Site Notes & Files','Activity','Settings'];
 if(!tabs.includes(psProjectTab))psProjectTab='Overview';let body='';
 if(psProjectTab==='Overview')body=psProjectOverview(job,p,s,health);
 else if(psProjectTab==='Orders & Pricing')body=psProjectOrderPricing(job,p,s);
 else if(psProjectTab==='Extras & Approvals')body=psProjectExtras(job,p,s);
 else if(psProjectTab==='Correspondence')body=psProjectCorrespondence(job,p);
 else if(psProjectTab==='Scope & Tasks')body=psProjectScopeTasks(job,p);
 else if(psProjectTab==='Materials')body=psProjectMaterials(job,p,s);
 else if(psProjectTab==='Procurement')body=psProjectProcurement(job,s);
 else if(psProjectTab==='Stock & Job Bin')body=psProjectStock(job,s);
 else if(psProjectTab==='Tools')body=typeof psToolCosting==='function'?psToolCosting(job.id):'<section class="project-360-card"><p>Tool register unavailable.</p></section>';
 else if(psProjectTab==='Costing & Margin')body=psProjectCosting(job,p,s);
 else if(psProjectTab==='Billing & Variations')body=psProjectBilling(job,p,s);
 else if(psProjectTab==='Site Notes & Files')body=psProjectDocuments(job,p);
 else if(psProjectTab==='Activity')body=psProjectActivity(job,p);
 else body=psProjectSettings(job,p);
 return '<section class="project-360-detail"><header class="project-360-detail-head"><div class="project-360-title"><button class="link-button" data-project-back>← Projects</button><span class="project-360-kicker">PROJECT DETAILS</span><h1>'+psProjectEsc(job.name)+'</h1><p>'+psProjectEsc(job.id)+' · '+psProjectEsc(customer(job.customerId)?.name||'No customer')+' · '+psProjectEsc(job.status)+'</p></div><div class="project-360-actions"><span class="project-health '+health.tone+'">'+health.level+'</span><button data-project-report>Project report</button></div></header>'+'<details class="project-progress-details"><summary><span>Project progress</span><b>'+psProjectEsc(psProjectStage(job.status))+'</b><small>View all stages</small></summary>'+psProjectProgressRail(job)+'</details>'+psProjectCommercialBar(job,s)+'<div class="project-144-layout">'+psProjectNavigation(tabs)+'<main class="project-360-body">'+body+'</main></div></section>';
}
function psProjectOrderPricing(job,p,s){
 const opts=(data.salesOrders||[]).filter(o=>!o.jobId&&o.customerId===job.customerId).map(o=>({id:o.id,name:o.id+' · '+(o.status||'Open')}));
 const rows=s.orders.map(o=>{const sell=(o.lines||[]).filter(l=>l.bundleRole!=='component').reduce((n,l)=>n+psProjectPence(Number(l.qty||0)*Number(typeof salesOrderLinePrice==='function'?salesOrderLinePrice(o,l):(l.unitPrice??l.price??0))),0);const cost=(o.lines||[]).filter(l=>l.bundleRole!=='head').reduce((n,l)=>n+psProjectPence(Number(l.qty||0)*Number(l.unitCost??product(l.productId)?.cost??0)),0);return '<tr><td><button class="link-button" data-open-so="'+psProjectEsc(o.id)+'">'+psProjectEsc(o.id)+'</button></td><td><span class="project-scope-tag">'+(o.variationId?'Extra · '+psProjectEsc(p.variations.find(v=>v.id===o.variationId)?.title||o.variationId):'Original scope')+'</span></td><td>'+psProjectCash(cost)+'</td><td>'+psProjectCash(sell)+'</td><td>'+psProjectCash(sell-cost)+'</td><td>'+psProjectEsc(o.status||'Open')+'</td></tr>';}).join('');
 return '<section class="project-360-card"><header><div><h3>Sales orders · cost & selling prices</h3><p>Live order values, excluding VAT. Open the order to change draft pricing at its source. Accepted project revenue remains locked to the quote and approved extras.</p></div></header>'+psProjectTable(['Sales order','Scope','Order cost estimate','Order selling price','Difference before other costs','Status'],rows,'No orders linked.')+psProjectForm(job,'link','<label>Unallocated customer order<select name="orderId" required>'+psProjectOptions(opts,'Choose sales order')+'</select></label><label>Allocate to<select name="variationId"><option value="">Original accepted scope</option>'+p.variations.filter(v=>v.status==='Approved').map(v=>'<option value="'+psProjectEsc(v.id)+'">Extra · '+psProjectEsc(v.title)+'</option>').join('')+'</select></label>','Allocate order to project')+'<div class="project-360-rule"><b>One linked source</b><span>Order prices are read from the sales order, not copied. Purchase costs feed the forecast through linked PO lines. Allocating an order does not add its selling price to the contract again.</span></div></section>'+psProjectProcurement(job,s);
}
function psProjectExtras(job,p,s){
 const rows=p.variations.map(v=>'<tr><td><span class="project-scope-tag">Extra</span><strong>'+psProjectEsc(v.title)+'</strong><small>'+psProjectEsc(v.id)+' · v'+(v.version||1)+'</small></td><td>'+money(v.costNet)+'</td><td>'+money(v.sellNet)+'</td><td>'+psProjectEsc(v.status)+(v.emailSentAt?'<small>Provider accepted '+psProjectEsc(v.emailSentAt)+'</small>':'<small>Not emailed from this app</small>')+'</td><td>'+(v.status==='Proposed'?'<button data-project-email-preview="'+psProjectEsc(v.id)+'">Preview email</button><button data-project-approve="'+psProjectEsc(v.id)+'">Record customer approval</button><button class="secondary" data-project-reject="'+psProjectEsc(v.id)+'">Reject</button>':psProjectEsc(v.approvalRef||'Decision recorded'))+'</td></tr>').join('');
 return '<section class="project-360-card"><header><div><h3>Extras & customer agreement</h3><p>Record the request, price it, notify the customer and retain approval evidence before allocating orders.</p></div></header>'+psProjectTable(['Extra','Estimated cost','Selling change','Status','Next action'],rows,'No extras recorded.')+'<details class="project-144-disclosure"><summary>Add a requested extra</summary>'+psProjectForm(job,'variation',psProjectInput('Extra title','title','','text','required')+psProjectInput('Customer selling change (£ ex VAT)','sellNet','','number','step="0.01" required')+psProjectInput('Estimated cost (£)','costNet','','number','min="0" step="0.01" required')+psProjectInput('VAT rate (%)','vatRate',20,'number','min="0" max="100" step="0.01" required')+'<label>Included scope and exclusions<textarea name="description" required maxlength="4000"></textarea></label>'+psProjectInput('Programme impact','programmeImpact','To be confirmed')+psProjectInput('Approval requested by','approvalDue','','date'),'Save requested extra')+'</details><div class="project-360-rule"><b>Sent is not approved</b><span>Email provider acceptance is logged separately from customer agreement. Record the customer’s reply or signed-document reference to approve; the agreed selling value updates once.</span></div></section>';
}
function psProjectCorrespondence(job,p){
 const rows=p.correspondence.slice().sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt)).map(c=>'<tr><td>'+psProjectEsc(new Date(c.occurredAt).toLocaleString('en-GB',{timeZone:'Europe/London'}))+'<small>UK time · '+psProjectEsc(c.user)+'</small></td><td>'+psProjectEsc(c.type)+'<small>'+psProjectEsc(c.source)+'</small></td><td>'+psProjectEsc(c.contact)+'</td><td class="project-wrap">'+psProjectEsc(c.body)+'<small>'+psProjectEsc(p.variations.find(v=>v.id===c.variationId)?.title||'Original project')+'</small></td><td>'+psProjectEsc(c.followUp||'—')+(c.followUp&&!c.completedAt?'<button data-project-followup="'+psProjectEsc(c.id)+'">Complete follow-up</button>':c.completedAt?'<small>Completed</small>':'')+'</td></tr>').join('');
 return '<section class="project-360-card"><header><div><h3>Correspondence</h3><p>Calls, emails and site conversations with source, date, time and follow-up. Manual email records do not prove delivery.</p></div></header>'+psProjectTable(['Occurred','Type / evidence','Contact','Conversation','Follow-up'],rows,'No correspondence yet.')+psProjectForm(job,'correspondence','<label>Type<select name="type">'+['Phone call','Site conversation','Email sent (manual)','Email received (manual)','Internal note'].map(t=>'<option>'+t+'</option>').join('')+'</select></label>'+psProjectInput('Contact','contact','','text','required')+psProjectInput('Occurred at (your device local time)','occurredAt','','datetime-local','required')+'<label>Related extra<select name="variationId">'+psProjectOptions(p.variations,'Original project')+'</select></label><label>Discussion / email summary<textarea name="body" required maxlength="4000"></textarea></label>'+psProjectInput('Follow-up date','followUp','','date'),'Save correspondence')+'</section>';
}
(function(){
 const groups=sidebarSubGroups;sidebarSubGroups=function(id){const g=groups(id).slice();if(id==='jobs')return ['Projects','Create Job'];return g;};
 const jobs=renderJobs;renderJobs=function(){if(selectedSubPage('jobs')==='Projects'){document.getElementById('screen-jobs').innerHTML=psProjectWorkspace();return;}jobs();};
 const remove=deleteJobReference;deleteJobReference=function(id){const j=data.jobs.find(j=>j.id===id);if(j?.project?.audit?.length||j?.project?.documents?.length||data.salesOrders.some(o=>o.jobId===id))return toast('This project has linked history. Retain it and update its status instead.');return remove(id);};
 document.addEventListener('submit',e=>{const finder=e.target.closest('[data-project-search-form]');if(finder){e.preventDefault();const values=new FormData(finder);psProjectSearch=String(values.get('search')||'');psProjectFilter=String(values.get('filter')||'all');render();return}const f=e.target.closest('[data-project-form]');if(!f)return;e.preventDefault();try{psProjectTransaction(f.dataset.projectForm,Object.fromEntries(new FormData(f)));render();}catch(error){toast(error.message);}});
 document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;const v={jobId:psProjectSelected};
  try{
   if(b.hasAttribute('data-project-clear-search')){psProjectSearch='';psProjectFilter='all';render();}
   else if(b.hasAttribute('data-project-home-view')){psProjectHomeView=b.dataset.projectHomeView;render();}
   else if(b.hasAttribute('data-project-open')){psProjectSelected=b.dataset.projectOpen;psProjectTab='Overview';openSidebarSubGroup('jobs','Projects');}
   else if(b.hasAttribute('data-project-new')){selectedJobId='__new';openSidebarSubGroup('jobs','Create Job');}
   else if(b.hasAttribute('data-project-back')){psProjectSelected='';render();}
   else if(b.hasAttribute('data-project-tab')){psProjectTab=b.dataset.projectTab;render();}
   else if(b.hasAttribute('data-project-edit-record')){selectedJobId=psProjectSelected;active='jobs';activeSubPage.jobs='Create Job';render();}
   else if(b.hasAttribute('data-project-create-bin')){createOrUpdateJobBin(psProjectSelected);}
   else if(b.hasAttribute('data-project-open-warehouse')){active='warehouse';activeSubPage.warehouse='Transfers';render();}
   else if(b.hasAttribute('data-open-po')){selectedPurchaseOrderId=b.dataset.openPo;purchaseOrderView='detail';active='purchase';activeSubPage.purchase='Purchase Orders';render();}
   else if(b.hasAttribute('data-project-material-remove')){psProjectTransaction('remove-material-plan',{...v,id:b.dataset.projectMaterialRemove});render();}
   else if(b.hasAttribute('data-project-approve')){const ref=prompt('Record the customer’s approval evidence: email reply date/reference or signed document. An email sent by us is not approval:');if(ref===null)return;psProjectTransaction('approve-extra',{...v,id:b.dataset.projectApprove,approvalRef:ref});render();}
   else if(b.hasAttribute('data-project-followup')){psProjectTransaction('complete-followup',{...v,id:b.dataset.projectFollowup});render();}
   else if(b.hasAttribute('data-project-email-preview')){psProjectEmailPreview(v.jobId,b.dataset.projectEmailPreview);}
   else if(b.hasAttribute('data-project-email-send')){b.disabled=true;await psProjectSendExtra(v.jobId,b.dataset.projectEmailSend);}
   else if(b.hasAttribute('data-project-reject')){psProjectTransaction('reject-extra',{...v,id:b.dataset.projectReject});render();}
   else if(b.hasAttribute('data-project-void')){const reason=prompt('Why is this cost being corrected? The original will remain in history.');if(reason===null)return;psProjectTransaction('void-cost',{...v,id:b.dataset.projectVoid,reason});render();}
   else if(b.hasAttribute('data-project-phase-remove')){psProjectTransaction('remove-phase',{...v,id:b.dataset.projectPhaseRemove});render();}
   else if(b.hasAttribute('data-project-ready')){psProjectTransaction('ready-phase',{...v,id:b.dataset.projectReady});render();}
   else if(b.hasAttribute('data-project-task-done')){psProjectTransaction('done-task',{...v,id:b.dataset.projectTaskDone});render();}
   else if(b.hasAttribute('data-project-finance-refresh')){await psFinanceRefresh();render();}
   else if(b.hasAttribute('data-project-invoice'))await psProjectInvoiceReview(v.jobId,b.dataset.projectInvoice);
   else if(b.hasAttribute('data-project-file'))await psProjectDownload(v.jobId,b.dataset.projectFile);
   else if(b.hasAttribute('data-project-doc-sync')){b.disabled=true;await psProjectSyncDocuments(v.jobId);render();}
   else if(b.hasAttribute('data-project-ai')){b.disabled=true;if(!await saveRemoteWorkspace(true))throw Error('Sync the project before requesting an AI review.');const response=await fetch('/api/project-review',{method:'POST',headers:{Authorization:'Bearer '+supabaseSession.access_token,'Content-Type':'application/json'},body:JSON.stringify({workspace:WORKSPACE_ID,jobId:v.jobId})});const result=await response.json();if(!response.ok)throw Error(result.error);const target=document.getElementById('psProjectAIResult');if(target)target.textContent=result.review+'\nBased on shared data saved '+result.asOf;b.disabled=false;}
   else if(b.hasAttribute('data-project-report')){const j=data.jobs.find(j=>j.id===v.jobId),s=psProjectSummary(j),esc=psProjectEsc;const report='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'+esc(j.name)+' project report</title><style>body{font:16px/1.5 system-ui;max-width:1000px;margin:40px auto;padding:0 20px;color:#18242C}h1,h2{line-height:1.2}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{text-align:left;padding:10px;border-bottom:1px solid #D8E0E4}small{color:#5F6D75}@media print{body{margin:0}}</style><h1>'+esc(j.name)+'</h1><p>'+esc(j.id)+' · '+esc(new Date().toLocaleString())+'</p><p>GBP excluding VAT. Management forecast; not statutory accounts.</p><table><tr><th>Measure</th><th>Amount</th></tr>'+[['Agreed revenue',s.revenue],['Forecast final cost',s.forecast],['Forecast profit',s.profit],['Projected margin',s.margin===null?null:s.margin]].map(([label,n])=>'<tr><td>'+esc(label)+'</td><td>'+esc(label==='Projected margin'?(n===null?'—':n.toFixed(1)+'%'):psProjectCash(n))+'</td></tr>').join('')+'</table><h2>Checks to review</h2>'+s.alerts.map(a=>'<p>'+esc(a.text)+'</p>').join('')+'</html>';const a=document.createElement('a'),url=URL.createObjectURL(new Blob([report],{type:'text/html'}));a.href=url;a.download=j.id+'-project-report.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  }catch(error){toast(error.message);b.disabled=false;}
 });
 document.addEventListener('click',e=>{const b=e.target.closest('[data-job-costing]');if(b){e.preventDefault();e.stopImmediatePropagation();psProjectSelected=b.dataset.jobCosting;psProjectTab='Overview';openSidebarSubGroup('jobs','Projects');}},true);
 const issues=psOperationalIssues;psOperationalIssues=function(){const result=issues();data.jobs.filter(j=>j.project).forEach(j=>psProjectSummary(j).alerts.forEach(a=>result.push({module:'jobs',record:j.id,message:a.text})));return result;};
 const saveJob=saveJobFromForm;saveJobFromForm=function(f){const v=Object.fromEntries(new FormData(f)),j=data.jobs.find(j=>j.id===v.id);if(j?.project){if(v.customerId!==j.customerId&&data.salesOrders.some(o=>o.jobId===j.id))return toast('Linked orders must retain their project customer.');if(['Completed','Invoiced'].includes(v.status)){const finance=typeof psFinanceSnapshot==='function'?(psFinanceSnapshot()||{}):{},blockers=psProjectCloseoutBlockers(j,data,finance);if(blockers.length)return toast('Project cannot close: '+blockers[0].message+(blockers.length>1?' '+(blockers.length-1)+' more close-out check(s) remain.':''));}}return saveJob(f);};
})();
function psProjectEmailPreview(jobId,extraId){
 const job=data.jobs.find(j=>j.id===jobId),extra=job?.project?.variations.find(v=>v.id===extraId);if(!extra)throw Error('Extra not found');psProjectExtraCheck(job,extra,data);const m=psProjectExtraMessage(job,extra),c=customer(job.customerId),vat=Math.round(m.sellNet*m.vatRate)/100;
 let dialog=document.getElementById('psProjectExtraEmail');if(!dialog){dialog=document.createElement('dialog');dialog.id='psProjectExtraEmail';dialog.className='project-email-dialog';document.body.appendChild(dialog)}
 dialog.innerHTML='<form method="dialog"><button class="secondary">Close preview</button></form><h2>Customer email preview</h2><p>To: '+psProjectEsc(c?.email||'Set customer email first')+'</p><section><h3>'+psProjectEsc(m.title)+'</h3><p>'+psProjectEsc(m.scope)+'</p><p>Additional price '+money(m.sellNet)+' excluding VAT<br>VAT ('+m.vatRate+'%) '+money(vat)+'<br><strong>Total '+money(m.sellNet+vat)+'</strong></p><p>Programme impact: '+psProjectEsc(m.programmeImpact)+'</p><p>Please reply to approve or ask questions, quoting '+psProjectEsc(m.extraId)+' v'+m.version+'. '+(m.approvalDue?'Reply requested by '+psProjectEsc(m.approvalDue)+'.':'')+'</p><p>This is additional to '+psProjectEsc(m.quoteRef||'your original agreement')+'. Payment follows the agreed billing schedule.</p></section><p>Sending logs provider acceptance. Customer approval must be recorded separately from their reply.</p><button data-project-email-send="'+psProjectEsc(extraId)+'" '+(!c?.email?'disabled':'')+'>Send approval request</button>';
 dialog.dataset.expected=JSON.stringify(m);dialog.dataset.recipient=c?.email||'';dialog.showModal();
}
async function psProjectSendExtra(jobId,extraId){
 const dialog=document.getElementById('psProjectExtraEmail'),expected=dialog.dataset.expected,recipient=dialog.dataset.recipient;
 if(!await saveRemoteWorkspace(true))throw Error('Sync this project before sending. Resolve any workspace conflict first.');
 const response=await fetch('/api/project-email',{method:'POST',headers:{Authorization:'Bearer '+supabaseSession.access_token,'Content-Type':'application/json'},body:JSON.stringify({workspace:WORKSPACE_ID,jobId,extraId,expected,recipient})});const result=await response.json();if(!response.ok)throw Error(result.error||'Email request failed');
 psProjectTransaction('extra-email-record',{jobId,id:extraId,...result});dialog.close();render();toast('Email accepted by provider. Await customer approval; delivery is not confirmed.');
}
